BEGIN;
DO $test$
DECLARE ceo uuid:='b8cbf27e-2391-4fb5-b061-f1488e8c3135'; k uuid:=gen_random_uuid(); j uuid; c public.development_jobs; a public.development_attempts; report jsonb; skill uuid; nonce uuid:=gen_random_uuid();
BEGIN
 PERFORM set_config('request.jwt.claim.sub',ceo::text,true);
 j:=public.request_development(k);IF j IS DISTINCT FROM public.request_development(k) THEN RAISE EXCEPTION 'Duplicate request';END IF;
 UPDATE public.audit_logs SET created_at=now()-interval '2 days' WHERE action IN ('skill_research.claimed','subtitle.claimed','development.claimed') AND created_at>=date_trunc('day',now());
 SELECT * INTO c FROM public.claim_development('920001/1');IF c.id IS DISTINCT FROM j THEN RAISE EXCEPTION 'Claim failed';END IF;
 IF (SELECT id FROM public.claim_development('920001/1')) IS DISTINCT FROM j OR EXISTS(SELECT 1 FROM public.claim_development('920002/1')) THEN RAISE EXCEPTION 'Duplicate concurrent claim';END IF;
 SELECT * INTO a FROM public.reserve_development_generation(j,c.lease_token,'920001/1',k,nonce,'{}');
 IF (SELECT generation_nonce FROM public.reserve_development_generation(j,c.lease_token,'920001/1',k,gen_random_uuid(),'{}')) IS DISTINCT FROM nonce THEN RAISE EXCEPTION 'Generation reservation duplicated';END IF;
 IF public.save_development_source(j,a.id,gen_random_uuid(),'920001/1','def analyze_srt(): pass','fixture','{}') THEN RAISE EXCEPTION 'Wrong lease saved source';END IF;
 PERFORM public.save_development_source(j,a.id,c.lease_token,'920001/1','def analyze_srt(): pass','fixture','{}');
 SELECT * INTO a FROM public.development_attempts WHERE id=a.id;
 report:=jsonb_build_object('harness_version','srt_quality_v1','source_sha256',a.source_sha256,'passed',true,'case_count',26,'passed_count',2,'isolation_passed',true);
 PERFORM public.save_development_test(j,a.id,c.lease_token,'920001/1',report,'https://github.com/Estrella-lc/ai-company-os/actions/runs/123');
 IF EXISTS(SELECT 1 FROM public.developed_skills WHERE job_id=j) THEN RAISE EXCEPTION 'Failing code published';END IF;
 SELECT * INTO a FROM public.reserve_development_generation(j,c.lease_token,'920001/1',gen_random_uuid(),gen_random_uuid(),'{"failures":[{"case":"overlap","error":"OVERLAP missing"}]}');
 IF a.number<>2 THEN RAISE EXCEPTION 'Repair attempt not recorded';END IF;
 PERFORM public.save_development_source(j,a.id,c.lease_token,'920001/1','def analyze_srt(text,duration_seconds=None): return {}','fixture','{}');
 SELECT * INTO a FROM public.development_attempts WHERE id=a.id;
 report:=jsonb_build_object('harness_version','srt_quality_v1','source_sha256',a.source_sha256,'passed',false,'case_count',26,'passed_count',10,'isolation_passed',true);
 PERFORM public.save_development_test(j,a.id,c.lease_token,'920001/1',report,'https://github.com/Estrella-lc/ai-company-os/actions/runs/123');
 SELECT * INTO a FROM public.reserve_development_generation(j,c.lease_token,'920001/1',gen_random_uuid(),gen_random_uuid(),'{"failures":[{"case":"empty","error":"EMPTY_INPUT missing"}]}');
 IF a.number<>3 THEN RAISE EXCEPTION 'Third candidate missing';END IF;
 PERFORM public.save_development_source(j,a.id,c.lease_token,'920001/1','def analyze_srt(text,duration_seconds=None): return {"valid": False}','fixture','{}');
 BEGIN PERFORM public.reserve_development_generation(j,c.lease_token,'920001/1',gen_random_uuid(),gen_random_uuid(),'{}');RAISE EXCEPTION 'Generation cap exceeded';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 UPDATE public.development_jobs SET lease_expires_at=now()-interval '1 second' WHERE id=j;
 SELECT * INTO c FROM public.claim_development('920002/1');
 IF c.id IS DISTINCT FROM j OR NOT EXISTS(SELECT 1 FROM public.development_attempts WHERE id=a.id AND state='candidate') THEN RAISE EXCEPTION 'Candidate recovery lost';END IF;
 IF public.save_development_test(j,a.id,c.lease_token,'920001/1',report,'https://github.com/Estrella-lc/ai-company-os/actions/runs/123') THEN RAISE EXCEPTION 'Old runner accepted';END IF;
 SELECT * INTO a FROM public.development_attempts WHERE id=a.id;
 report:=jsonb_build_object('harness_version','srt_quality_v1','source_sha256',a.source_sha256,'passed',true,'case_count',26,'passed_count',26,'isolation_passed',true);
 PERFORM public.save_development_test(j,a.id,c.lease_token,'920002/1',report,'https://github.com/Estrella-lc/ai-company-os/actions/runs/123');
 IF NOT public.save_development_test(j,a.id,c.lease_token,'920002/1',report,'https://github.com/Estrella-lc/ai-company-os/actions/runs/123') THEN RAISE EXCEPTION 'Terminal callback not idempotent';END IF;
 SELECT id INTO skill FROM public.developed_skills WHERE job_id=j AND status='verified';IF skill IS NULL THEN RAISE EXCEPTION 'Verified source missing';END IF;
 PERFORM public.release_developed_skill(skill);PERFORM public.release_developed_skill(skill);
 IF NOT EXISTS(SELECT 1 FROM public.developed_skills WHERE id=skill AND status='released' AND origin='company_developed') THEN RAISE EXCEPTION 'Release failed';END IF;
 INSERT INTO public.audit_logs(actor_type,action,resource_type,resource_id) VALUES('worker','development.claimed','fixture','budget');
 IF EXISTS(SELECT 1 FROM public.claim_subtitle_job('920003/1')) OR EXISTS(SELECT 1 FROM public.claim_skill_research('920003/1')) THEN RAISE EXCEPTION 'Shared budget broken';END IF;
 PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 BEGIN PERFORM public.request_development(gen_random_uuid());RAISE EXCEPTION 'Unauthorized request';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_function_privilege('authenticated','public.claim_development(text)','EXECUTE') OR has_table_privilege('authenticated','public.development_attempts','INSERT') THEN RAISE EXCEPTION 'Browser write expansion';END IF;
END $test$;
SET LOCAL ROLE authenticated;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.development_jobs) OR EXISTS(SELECT 1 FROM public.development_attempts) OR EXISTS(SELECT 1 FROM public.developed_skills) THEN RAISE EXCEPTION 'RLS cross-owner leak';END IF;END $$;
RESET ROLE;
ROLLBACK;
SELECT 'PASS: recruitment, generation idempotency, failed-test rejection, repair provenance, recovery, stale identity, release, shared budget and RLS; rolled back' AS checks;
